# The conditions of the security research exemption,
# 37 CFR 201.40(b)(18), as a checklist (not legal advice)
def exemption_applies(r):
    checks = {
        "lawfully acquired device, or owner authorised": r["lawful_device"],
        "solely for good-faith security research":       r["purpose"] == "security",
        "environment designed to avoid harm":            r["lab_only"],
        "results used mainly to promote security":       r["publish_to_fix"],
        "not used to facilitate infringement":           not r["shares_copies"],
    }
    for name, ok in checks.items():
        print(("ok   " if ok else "FAIL ") + name)
    return all(checks.values())

router = {"lawful_device": True, "purpose": "security", "lab_only": True,
          "publish_to_fix": True, "shares_copies": True}
print("covered:", exemption_applies(router))

/* "Fix" for a leak: free the request if setup fails */
struct req { char name[16]; };
int setup(struct req *r, int fail) {
    if (fail) {
        free(r);            /* the patch adds this line */
        return -1;
    }
    return 0;
}
/* ...but the caller still uses r on the error path: */
if (setup(r, 1) < 0)
    printf("setup failed for %s\n", r->name);

